import React, { useState } from 'react';

export default function LoginModal({ isOpen, onClose, onLoginSuccess }) {
  const [email, setEmail] = useState('admin@diyataxi.com');
  const [password, setPassword] = useState('admin123');
  const [error, setError] = useState('');

  if (!isOpen) return null;

  const handleSubmit = (e) => {
    e.preventDefault();
    if (email.trim().toLowerCase() === 'admin@diyataxi.com' && password === 'admin123') {
      setError('');
      onLoginSuccess({
        role: 'admin',
        name: 'Operations Admin',
        email: 'admin@diyataxi.com'
      });
      onClose();
    } else {
      setError('Invalid Admin credentials. (Use: admin@diyataxi.com / admin123)');
    }
  };

  const handleQuickAdminLogin = () => {
    setError('');
    onLoginSuccess({
      role: 'admin',
      name: 'Operations Admin',
      email: 'admin@diyataxi.com'
    });
    onClose();
  };

  return (
    <div className="modal-overlay open">
      <div className="modal-card" style={{ maxWidth: '440px' }}>
        <div className="modal-header">
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
            <div style={{
              width: '36px',
              height: '36px',
              borderRadius: '10px',
              background: 'linear-gradient(135deg, #f59e0b, #d97706)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              fontSize: '18px',
              color: '#080c14'
            }}>
              🔐
            </div>
            <div>
              <h3 style={{ fontSize: '18px', fontWeight: 700 }}>Admin Portal Login</h3>
              <div style={{ fontSize: '12px', color: 'var(--text-muted)' }}>Authorized personnel only</div>
            </div>
          </div>
          <button className="modal-close-btn" onClick={onClose}>&times;</button>
        </div>

        <div className="modal-body">
          {error && (
            <div style={{
              background: 'rgba(239, 68, 68, 0.15)',
              border: '1px solid rgba(239, 68, 68, 0.4)',
              color: '#f87171',
              padding: '10px 14px',
              borderRadius: '8px',
              fontSize: '13px',
              marginBottom: '16px'
            }}>
              ⚠️ {error}
            </div>
          )}

          <form onSubmit={handleSubmit}>
            <div style={{ marginBottom: '16px' }}>
              <label style={{ display: 'block', fontSize: '12px', fontWeight: 700, color: 'var(--text-secondary)', marginBottom: '6px', textTransform: 'uppercase' }}>
                Admin Email
              </label>
              <input
                type="email"
                className="input-control"
                style={{ width: '100%' }}
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder="admin@diyataxi.com"
                required
              />
            </div>

            <div style={{ marginBottom: '22px' }}>
              <label style={{ display: 'block', fontSize: '12px', fontWeight: 700, color: 'var(--text-secondary)', marginBottom: '6px', textTransform: 'uppercase' }}>
                Password
              </label>
              <input
                type="password"
                className="input-control"
                style={{ width: '100%' }}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="••••••••"
                required
              />
            </div>

            <button type="submit" className="btn btn-primary" style={{ width: '100%', padding: '12px', fontSize: '15px', marginBottom: '12px' }}>
              Login to Admin Dashboard 🚀
            </button>

            <button
              type="button"
              className="btn btn-secondary"
              onClick={handleQuickAdminLogin}
              style={{ width: '100%', padding: '10px', fontSize: '13px' }}
            >
              ⚡ 1-Click Quick Demo Admin Login
            </button>
          </form>

          <div style={{ marginTop: '20px', padding: '12px', background: 'rgba(255,255,255,0.03)', borderRadius: '8px', fontSize: '12px', color: 'var(--text-muted)' }}>
            <span style={{ color: 'var(--primary)', fontWeight: 600 }}>Demo Admin:</span> admin@diyataxi.com &bull; <span style={{ color: 'var(--primary)', fontWeight: 600 }}>Password:</span> admin123
          </div>
        </div>
      </div>
    </div>
  );
}
